#!/usr/bin/env bash
set -u

work=/tmp/audit-work/candidate-src
cd "$work" || exit 99

python3 /audit-output/evidence/concrete_python_oracle.py
echo "PYTHON_EXIT_STATUS=$?"

run_case() {
  name=$1
  input=$2
  echo "CASE=$name"
  echo "COMMAND=krun solution.mpy --definition concrete-kompiled -cINPUT=$input"
  krun solution.mpy --definition concrete-kompiled "-cINPUT=$input"
  echo "KRUN_EXIT_STATUS=$?"
}

run_case normal_odd 'cons(3, cons(1, cons(2, cons(4, cons(5, nil)))))'
run_case normal_even 'cons(-10, cons(4, cons(6, cons(1000, cons(10, cons(20, nil))))))'
run_case singleton 'cons(7, nil)'
run_case length_two 'cons(2, cons(10, nil))'
run_case empty 'nil'
run_case even_four 'cons(1, cons(2, cons(3, cons(4, nil))))'
run_case negative_odd 'cons(-8, cons(-1, cons(-4, nil)))'
run_case even_duplicates 'cons(5, cons(5, cons(5, cons(5, nil))))'
run_case huge_even 'cons(, cons(, cons(, cons(, nil))))'
